// === 自动检测IP+登录 v2 (修复IP过滤) ===
const DEBUG=global.get('mcSim_debug')||false;
const isReauth=(msg&&msg.payload==='reauth');
const preExistingJwt=global.get('mcSim_jwtToken')||'';

// null消息守卫
if(!msg){return;}

// 401重登守卫: 如果JWT尚在且采集未停, 跳过
if(isReauth&&preExistingJwt&&global.get('mcSim_configReady')){
    if(DEBUG)node.warn('[Init] Re-auth skipped, session valid');
    global.set('mcSim_reauthInProgress',false);
    return;
}

const isFirstRun=!preExistingJwt&&!isReauth;
const isRefresh=!isReauth&&!isFirstRun;

// === IP检测 v2: 接受真实LAN IP, 跳过虚拟网卡 ===
let detectedIp='127.0.0.1';
try{
    const os=global.get('os');
    const nets=os.networkInterfaces();
    // 虚拟网卡特征: Docker(172.17.x), Hyper-V(172.x), VirtualBox(192.168.56.x), APIPA(169.254.x)
    const VIRTUAL_PREFIXES=['172.17.','192.168.56.','169.254.'];
    function isVirtual(addr){
        for(var i=0;i<VIRTUAL_PREFIXES.length;i++){
            if(addr.startsWith(VIRTUAL_PREFIXES[i]))return true;
        }
        return false;
    }
    var candidates=[];
    for(const name of Object.keys(nets)){
        for(const net of nets[name]){
            if(net.family==='IPv4'&&!net.internal&&!isVirtual(net.address)){
                candidates.push(net.address);
            }
        }
    }
    // 优先选 192.168.x 或 10.x (真实LAN), 其次选其他的
    for(var i=0;i<candidates.length;i++){
        if(candidates[i].startsWith('192.168.')||candidates[i].startsWith('10.')){
            detectedIp=candidates[i];break;
        }
    }
    if(detectedIp==='127.0.0.1'&&candidates.length>0){
        if(DEBUG)node.warn('[AutoIP] No 192.168/10.x found, using: '+candidates[0]);
        detectedIp=candidates[0];
    }
    if(DEBUG&&detectedIp==='127.0.0.1')node.warn('[AutoIP] No LAN IP found, using 127.0.0.1');
}catch(e){if(DEBUG)node.warn('[AutoIP] os not available: '+e.message);}

const hostPcIp=detectedIp!=='127.0.0.1'?detectedIp:(global.get('mcSim_hostPcIp')||'127.0.0.1');
global.set('mcSim_hostPcIp',hostPcIp);
// nodeId 将在 fn-config 中动态获取, 此处仅做初始占位
global.set('mcSim_nodeId',global.get('mcSim_nodeId')||0);

// Backend配置(保留已有值, 允许settings.js覆盖)
global.set('mcSim_backendHost',global.get('mcSim_backendHost')||'127.0.0.1');
global.set('mcSim_backendPort',global.get('mcSim_backendPort')||9099);

// === 首次运行: 初始化所有状态 ===
if(isFirstRun){
    global.set('mcSim_devices',[]);
    global.set('mcSim_tagConfigs',[]);
    global.set('mcSim_devCommStatus',{});
    global.set('mcSim_lastGoodTags',{});
    global.set('mcSim_pgSuccessCount',0);
    global.set('mcSim_pgPrevCount',0);
    global.set('mcSim_mcRetryCount',{});
    global.set('mcSim_lastAlarmTime',{});
    global.set('mcSim_lastScanTime',0);
    global.set('mcSim_reauthInProgress',false);
    global.set('mcSim_debug',DEBUG);
    global.set('mcSim_backendUser',global.get('mcSim_backendUser')||'admin');
    global.set('mcSim_backendPass',global.get('mcSim_backendPass')||'');
    global.set('mcSim_apiKey',global.get('mcSim_apiKey')||'');
    if(DEBUG)node.warn('[Init] First run, hostPcIp='+hostPcIp);
}

// 刷新路径: 不中断采集
if(isRefresh){
    if(DEBUG)node.warn('[Init] Periodic refresh, configReady stays true');
    global.set('mcSim_reauthInProgress',false);
}

// 重登路径: 清JWT重登 (幂等: 如果已有登录进行中则跳过)
if(isReauth){
    if(global.get('mcSim_reauthInFlight')){
        if(DEBUG)node.warn('[Init] Re-auth already in flight, skip duplicate');
        return;
    }
    global.set('mcSim_jwtToken','');
    global.set('mcSim_configReady',false);
    global.set('mcSim_reauthInProgress',true);
    global.set('mcSim_reauthInFlight',true);
    setTimeout(function(){global.set('mcSim_reauthInFlight',false);},30000);
    if(DEBUG)node.warn('[Init] 401 reauth, full re-login');
}

const user=global.get('mcSim_backendUser')||'admin';
const pass=global.get('mcSim_backendPass')||'';
var host=global.get('mcSim_backendHost')||'127.0.0.1';var port=global.get('mcSim_backendPort')||9099;msg.url='http://'+host+':'+port+'/login';msg.payload='username='+user+'&password='+pass;
return msg;

// === 发现本PC所有设备+点位 v2 (nodeId反查+protocolParams) ===
var http=global.get('http');
var HOST=global.get('mcSim_backendHost')||'127.0.0.1';
var PORT=global.get('mcSim_backendPort')||9099;
var DEBUG=global.get('mcSim_debug')||false;
var myHostPcIp=global.get('mcSim_hostPcIp')||'127.0.0.1';
var now=new Date().toLocaleString('sv-SE').replace(' ','T');
var apiKey=global.get('mcSim_apiKey')||'';

// 1. 解析JWT
var jwtToken='';
try{var r=JSON.parse(msg.payload);jwtToken=(r.data&&r.data.token)?r.data.token:(r.token||'');}catch(e){}
if(!jwtToken){
    if(DEBUG)node.warn('[Config] JWT FAIL: '+msg.payload.substring(0,80));
    global.set('mcSim_reauthInProgress',false);
global.set('mcSim_reauthInFlight',false);
    return;
}
global.set('mcSim_jwtToken',jwtToken);
global.set('mcSim_reauthInProgress',false);
global.set('mcSim_reauthInFlight',false);
if(DEBUG)node.warn('[Config] JWT OK, hostPcIp='+myHostPcIp);

// 2. 反查/注册 nodeId (调用 heartbeat → 自动注册)
function discoverNodeId(callback){
    var nodeParams='host_pc_ip='+myHostPcIp+'&node_ip='+myHostPcIp+'&running_flows=5&memory_usage_mb='+(Math.round((global.get('process').memoryUsage().rss||0)/1048576)||0);
    var nodeOpts={hostname:HOST,port:PORT,path:'/monitor/heartbeat?'+nodeParams,method:'POST',
        headers:{'X-API-Key':apiKey,'Authorization':'Bearer '+jwtToken,'Content-Type':'application/json'}};
    var nr=http.request(nodeOpts,function(res){
        var b='';res.on('data',function(d){b+=d;});
        res.on('end',function(){
            try{
                var j=JSON.parse(b);
                var nid=(j.data&&j.data.node_id)?j.data.node_id:0;
                if(nid>0){
                    global.set('mcSim_nodeId',nid);
                    if(DEBUG)node.warn('[Config] Node registered, nodeId='+nid);
                    callback(nid);
                }else{
                    // 后端不返回nodeId → 用hash兜底
                    var hash=0;for(var i=0;i<myHostPcIp.length;i++){hash=((hash<<5)-hash)+myHostPcIp.charCodeAt(i);hash|=0;}
                    nid=Math.abs(hash)%9000+1000;
                    global.set('mcSim_nodeId',nid);
                    if(DEBUG)node.warn('[Config] nodeId from hash: '+nid);
                    callback(nid);
                }
            }catch(e){
                if(DEBUG)node.warn('[Config] nodeId parse err: '+e.message);
                callback(0);
            }
        });
    });
    nr.setTimeout(5000,function(){nr.destroy();callback(0);});
    nr.on('error',function(e){if(DEBUG)node.warn('[Config] nodeId err: '+e.message);callback(0);});
    nr.write('{}');nr.end();
}

// 3. 拉取全局点位
function discoverTags(nodeId){
    var tagPath='/plc/tag/global/list?page_size=10000';
    var tagReq=http.request({
        hostname:HOST,port:PORT,path:tagPath,method:'GET',
        headers:{'Authorization':'Bearer '+jwtToken}
    },function(res){
        var body='';
        res.on('data',function(d){body+=d;});
        res.on('end',function(){
            try{
                var r=JSON.parse(body);
                if(r.code!==200){
                    node.warn('[Config] tag API err, configReady=true with empty list (will retry on 5min refresh)');
                    global.set('mcSim_configReady',true);
                    node.send([null,{payload:{}}]);
                    return;
                }
                var records=r.rows||(r.data&&r.data.records)||[];
                if(records.length===0){
                    node.warn('[Config] No tags in system, configReady=true with empty list');
                    global.set('mcSim_configReady',true);
                    node.send([null,{payload:{}}]);
                    return;
                }

                // 4. 按(deviceId)分组
                var byDevice={};
                records.forEach(function(t){
                    var did=t.deviceId||1;
                    var key=did;
                    if(!byDevice[key]){
                        byDevice[key]={
                            id:did,
                            deviceName:t.deviceName||('PLC-'+did),
                            hostPcIp:t.hostPcIp||myHostPcIp,
                            plcIp:t.plcIp||'127.0.0.1',
                            plcPort:t.plcPort||5007,
                            comType:t.comType||'MC_Protocol',
                            mcFrame:t.mcFrame||'3E',
                            plcSeries:t.plcSeries||'Q',
                            stationNo:t.stationNo||0,
                            networkNo:t.networkNo||0,
                            scanIntervalMs:t.scanIntervalMs||1000,
                            commTimeoutMs:t.commTimeoutMs||3000,
                            retryCount:t.retryCount||2,
                            retryIntervalMs:t.retryIntervalMs||500,
                            triggerKind:t.triggerKind||1,
                            status:t.status||'0',
                            protocolParams:t.protocolParams||{},
                            tags:[]
                        };
                    }
                    byDevice[key].tags.push({
                        id:t.id,
                        addr:(function(){var s=String(t.registerAddress||'0').replace(/\D/g,'');var base=(t.registerType==='X'||t.registerType==='Y')?8:10;return parseInt(s,base)||0;})(),
                        regAddr:t.registerAddress||'',
                        regType:t.registerType||'D',
                        name:t.tagName,
                        dtype:t.dataType||'INT16',
                        tform:t.transformType||'none',
                        slope:t.transformSlopeA||1,
                        offset:t.transformOffsetB||0,
                        unit:t.engUnit||''
                    });
                });

                // 5. 筛选: 只取本PC管理的启用设备
                var myDevices=[];
                var allDevIds=Object.keys(byDevice);
                allDevIds.forEach(function(did){
                    var dev=byDevice[did];
                    if(String(dev.status)!=='0')return;
                    if(dev.hostPcIp!==myHostPcIp)return;
                    // 放宽检测: Modbus设备不需要D寄存器
                    if(dev.comType==='MC_Protocol'){
                        var addrs=dev.tags.map(function(t){return t.addr;}).filter(function(a){return a>=0;}).sort(function(a,b){return a-b;});
                        if(addrs.length===0){if(DEBUG)node.warn('[Config] Device '+dev.deviceName+' has no valid registers, skipped');return;}
                        dev.mcReadAddr='D'+addrs[0]+','+(addrs[addrs.length-1]-addrs[0]+1);
                    }
                    dev.tagCount=dev.tags.length;
                    // 合并 protocolParams: 后端JSON优先, 否则用MC平铺字段兜底
                    if(!dev.protocolParams||Object.keys(dev.protocolParams).length===0){
                        dev.protocolParams={mcFrame:dev.mcFrame,stationNo:dev.stationNo,networkNo:dev.networkNo,plcSeries:dev.plcSeries};
                    }
                    myDevices.push(dev);
                });

                global.set('mcSim_devices',myDevices);
                global.set('mcSim_tagConfigs',myDevices.reduce(function(acc,dev){acc[dev.id]=dev.tags;return acc;},{}));
                global.set('mcSim_configReady',true);
                global.set('mcSim_triggerLastRaw',{});
                global.set('mcSim_triggerForceTimes',{});
                global.set('mcSim_handshakeFlags',{});

                if(DEBUG){
                    node.warn('[Config] Discovered '+myDevices.length+' devices (nodeId='+nodeId+'):');
                    myDevices.forEach(function(d){node.warn('  '+d.deviceName+' ('+d.plcIp+':'+d.plcPort+') '+d.tagCount+' tags comType='+d.comType);});
                }

                // 6. 触发首次采集 + 发布MQTT上线
                node.send([null,{payload:{}}]);
                publishMqtt(myDevices,myHostPcIp,nodeId);

            }catch(e){
                if(DEBUG)node.warn('[Config] parse err: '+e.message);
            }
        });
    });
    tagReq.on('error',function(e){node.warn('[Config] tag fetch err: '+e.message);global.set('mcSim_configReady',true);node.send([null,{payload:{}}]);});
    tagReq.setTimeout(5000,function(){tagReq.destroy();node.warn('[Config] tag fetch timeout');global.set('mcSim_configReady',true);node.send([null,{payload:{}}]);});
    tagReq.end();
}

function publishMqtt(devices,hostIp,nodeId){
    var ts=now||new Date().toLocaleString('sv-SE').replace(' ','T');
    var devList=devices.map(function(d){return {device_id:d.id,device_name:d.deviceName,tag_count:d.tagCount};});
    var nid=nodeId||global.get('mcSim_nodeId')||999;
    node.send([{topic:'edgelink/nodes/'+nid+'/status',payload:JSON.stringify({node_id:nid,host_pc_ip:hostIp,status:'online',device_count:devices.length,devices:devList,ts:ts}),qos:1,retain:true},null]);
}

// 启动: 反查nodeId → 拉点位
discoverNodeId(function(nid){discoverTags(nid);});
return;

// === 心跳 v2 (修复异步reauth死代码) ===
var http=global.get('http');
var HOST=global.get('mcSim_backendHost')||'127.0.0.1';
var PORT=global.get('mcSim_backendPort')||9099;
var nodeId=global.get('mcSim_nodeId')||999;
var hostPcIp=global.get('mcSim_hostPcIp')||'127.0.0.1';
var jwt=global.get('mcSim_jwtToken')||'';
var DEBUG=global.get('mcSim_debug')||false;
var devices=global.get('mcSim_devices')||[];
var now=new Date().toLocaleString('sv-SE').replace(' ','T');

var mem=0;
try{mem=Math.round(global.get('process').memoryUsage().rss/1024/1024);global.set("mcSim_lastMemoryMb",mem);}catch(e){mem=global.get("mcSim_lastMemoryMb")||0;}

var devList=devices.map(function(d){return {id:d.id,name:d.deviceName,status:d.status};});
var mqttMsg={topic:'edgelink/heartbeat/'+nodeId,payload:JSON.stringify({node_id:nodeId,host_pc_ip:hostPcIp,device_count:devices.length,devices:devList,running_flows:5,memory_usage_mb:mem,status:'online',ts:now}),qos:1,retain:false};

var params='host_pc_ip='+hostPcIp+'&node_ip='+hostPcIp+'&running_flows=5&memory_usage_mb='+mem;
var apiKey=global.get('mcSim_apiKey')||'';
var opts={hostname:HOST,port:PORT,path:'/monitor/heartbeat?'+params,method:'POST',headers:{'X-API-Key':apiKey,'Authorization':'Bearer '+jwt,'Content-Type':'application/json'}};

function sendResult(reauth){
    if(reauth){
        node.send([mqttMsg,{payload:'reauth'}]);
    }else{
        node.send([mqttMsg,null]);
    }
}

var responded=false;
var req=http.request(opts,function(res){
    var b='';
    res.on('data',function(d){b+=d;});
    res.on('end',function(){
        if(responded)return;
        responded=true;
        var reauth=false;
        if(res.statusCode===401){
            if(!global.get('mcSim_reauthInProgress')){
                node.warn('[HB] JWT expired, trigger re-login');
                global.set('mcSim_jwtToken','');
                global.set('mcSim_configReady',false);
                global.set('mcSim_reauthInProgress',true);
                reauth=true;
            }
        }
        // 解析nodeId (后端heartbeat返回 {node_id:...})
        try{
            var j=JSON.parse(b);
            var nid=(j.data&&j.data.node_id)?j.data.node_id:0;
            if(nid>0&&nid!==nodeId){
                global.set('mcSim_nodeId',nid);
                if(DEBUG)node.warn('[HB] nodeId updated: '+nodeId+' → '+nid);
            }
        }catch(e){}
        node.status({fill:res.statusCode===200?'green':'red',shape:'dot',text:'HB '+res.statusCode});
        sendResult(reauth);
    });
});
req.setTimeout(5000,function(){
    if(responded)return;
    responded=true;
    req.destroy();
    if(DEBUG)node.warn('[HB] timeout');
    sendResult(false);
});
req.on('error',function(e){
    if(responded)return;
    responded=true;
    if(DEBUG)node.warn('[HB] err: '+e.message);
    sendResult(false);
});
req.write('{}');
req.end();

// === 设备读取列表构建器 v2 (协议可插拔) ===
if(!msg){return null;}

var configReady=global.get('mcSim_configReady')||false;
if(!configReady){
    node.status({fill:'grey',shape:'dot',text:'wait config'});
    return null;
}

var now=Date.now();
var lastScan=global.get('mcSim_lastScanTime')||0;
var devices=global.get('mcSim_devices')||[];

if(devices.length===0){
    node.status({fill:'grey',shape:'dot',text:'no devices'});
    return null;
}

var interval=1000;
if(devices.length>0){
    var minInterval=Math.min.apply(null,devices.map(function(d){return d.scanIntervalMs||1000;}));
    interval=Math.max(minInterval,200);
}

if(now-lastScan<interval){return null;}
global.set('mcSim_lastScanTime',now);

// === 驱动注册表（comType → driverType 映射，可由 settings.js 覆盖） ===
var DRIVER_REGISTRY=global.get('mcSim_driverRegistry')||{
    'MC_Protocol':'driver-mc-protocol',
    'Modbus_TCP':'driver-modbus-tcp'
};

node.status({fill:'green',shape:'dot',text:devices.length+' devs'});

// === 触发模式过滤 ===
var handshakeFlags=global.get('mcSim_handshakeFlags')||{};
var triggerLastRaw=global.get('mcSim_triggerLastRaw')||{};
var triggerForceTimes=global.get('mcSim_triggerForceTimes')||{};
var lastGoodTags=global.get('mcSim_lastGoodTags')||{};
var activeDevices=[];
devices.forEach(function(d){
    // triggerKind=0 握手触发: 仅当收到外部MQTT触发才采集
    if(d.triggerKind===0){
        if(!handshakeFlags[d.id])return;
        delete handshakeFlags[d.id];global.set('mcSim_handshakeFlags',handshakeFlags);
    }
    // triggerKind=2 变化触发: 值未变则跳过, 强制5s间隔兜底
    if(d.triggerKind===2){
        var forceDue=!triggerForceTimes[d.id]||(now-triggerForceTimes[d.id]>=5000);
        if(!forceDue&&lastGoodTags[d.id]){
            var prevVals=triggerLastRaw[d.id]||{};
            var changed=false;
            lastGoodTags[d.id].forEach(function(v){if(prevVals[v.tag_id]!==v.raw_value)changed=true;});
            if(!changed)return;
        }
        if(forceDue){triggerForceTimes[d.id]=now;global.set('mcSim_triggerForceTimes',triggerForceTimes);}
        if(lastGoodTags[d.id]){var newVals={};lastGoodTags[d.id].forEach(function(v){newVals[v.tag_id]=v.raw_value;});
        triggerLastRaw[d.id]=newVals;global.set('mcSim_triggerLastRaw',triggerLastRaw);
    }
    }
    activeDevices.push(d);
});

// 产出: 为每个设备附加 driverType 和标准化字段（contract v1）
msg.devices=activeDevices.map(function(d){
    var driverType=DRIVER_REGISTRY[d.comType]||null;
    return {
        deviceId:d.id,
        deviceName:d.deviceName,
        comType:d.comType,
        driverType:driverType,
        connection:{ip:d.plcIp,port:d.plcPort},
        protocolParams:d.protocolParams||{mcFrame:d.mcFrame,stationNo:d.stationNo,networkNo:d.networkNo,plcSeries:d.plcSeries},
        tags:d.tags||[],
        timeout:d.commTimeoutMs||3000,
        maxRetries:d.retryCount||2,
        retryInterval:d.retryIntervalMs||300,
        triggerKind:d.triggerKind||1
    };
});

msg.roundId=now;
return msg;

// === 驱动路由器 v2 (4E帧 + X/Y/M寄存器 + 智能批量 + driverType) ===
var net=global.get('net');
var SIM_MODE=global.get('mcSim_simulationMode')||false;
var devices=msg.devices||[];
var DEBUG=global.get('mcSim_debug')||false;
var roundId=msg.roundId||Date.now();
var ROUND_TIMEOUT_MS=15000;
var roundStart=Date.now();

if(devices.length===0){return null;}

var results=[];

// MC 软元件代码映射 (3E/4E帧共用)
var MC_DEVICE_CODES={
    'D':0xA8,'W':0xB4,'X':0x9C,'Y':0x9D,'M':0x90,'L':0x92,'B':0xA0,'R':0xAF
};
// 位软元件(bit device): 每16位打包成1字, 需拆解为布尔值
var BIT_DEVICES={'X':true,'Y':true,'M':true,'L':true,'B':true};

// ============================================================
// Driver: MC Protocol (3E/4E + 多寄存器类型 + 智能批量)
// ============================================================
function driverMCProtocol(dev, done){
    var pp=dev.protocolParams||{};
    var mcFrame=pp.mcFrame||'3E';

    if(SIM_MODE||!net){
        if(SIM_MODE){
            setTimeout(function(){
                var simData={};
                (dev.tags||[]).forEach(function(t){
                    simData[t.id]={rawValue:Math.floor(Math.random()*1000),quality:0,ts:new Date().toLocaleString('sv-SE').replace(' ','T')};
                });
                var ok=Math.random()>0.1;
                done({deviceId:dev.deviceId,deviceName:dev.deviceName,success:ok,data:simData,plcIp:dev.connection.ip,plcPort:dev.connection.port,error:ok?null:'Simulated timeout',driverType:'driver-mc-protocol'});
            },10+Math.random()*30);
        }else{
            if(DEBUG)node.warn('[MC-Driver] net not available');
            done({deviceId:dev.deviceId,deviceName:dev.deviceName,success:false,error:'net unavailable',data:{},plcIp:dev.connection.ip,plcPort:dev.connection.port,driverType:'driver-mc-protocol'});
        }
        return;
    }

    // 按寄存器类型 + 地址聚类 (Fix #9: 稀疏点位智能分组)
    var byRegType={};
    (dev.tags||[]).forEach(function(t){
        var rt=t.regType||'D';
        if(!byRegType[rt])byRegType[rt]=[];
        byRegType[rt].push(t);
    });

    var regGroups=[];
    var MAX_GAP=20;
    Object.keys(byRegType).forEach(function(rt){
        var tags=byRegType[rt].sort(function(a,b){return a.addr-b.addr;});
        var cluster=[tags[0]];
        for(var i=1;i<tags.length;i++){
            var gap=tags[i].addr-cluster[cluster.length-1].addr;
            if(gap<=MAX_GAP&&(cluster.length<50)){
                cluster.push(tags[i]);
            }else{
                regGroups.push({regType:rt,tags:cluster});
                cluster=[tags[i]];
            }
        }
        if(cluster.length>0)regGroups.push({regType:rt,tags:cluster});
    });

    var allStdData={};
    var completedGroups=0;
    var hasFailed=false;
    var firstError='';

    function buildMCFrame(startAddr, wordCount, stationNo, regType, frameType){
        var deviceCode=MC_DEVICE_CODES[regType]||0xA8;
        if(frameType==='4E'){
            // 4E帧: 简化版22字节(无SN) / 标准版24字节(带SN), 起始地址4字节(小端)
            var hasSN=pp.serialNo!=null&&pp.serialNo!==0;
            var bufLen=hasSN?24:22;
            var buf=Buffer.alloc(bufLen);
            buf[0]=0x54;buf[1]=0x00;
            buf[2]=pp.networkNo||0;
            buf[3]=0xFF;
            buf[4]=0xFF;buf[5]=0x03;
            buf[6]=pp.stationNo||0;
            buf[7]=hasSN?0x0F:0x0D;buf[8]=0x00;
            buf[9]=0x10;buf[10]=0x00;
            var off=11;
            if(hasSN){buf[off]=pp.serialNo&0xFF;buf[off+1]=(pp.serialNo>>8)&0xFF;off+=2;}
            buf[off]=0x01;buf[off+1]=0x04;off+=2;
            buf[off]=BIT_DEVICES[regType]?0x01:0x00;buf[off+1]=0x00;off+=2;  // 0001=bit 0000=word
            buf[off]=startAddr&0xFF;buf[off+1]=(startAddr>>8)&0xFF;buf[off+2]=(startAddr>>16)&0xFF;buf[off+3]=(startAddr>>24)&0xFF;off+=4;
            buf[off]=deviceCode;off+=1;
            buf[off]=wordCount&0xFF;buf[off+1]=(wordCount>>8)&0xFF;
            return buf;
        }
        // 3E帧 (默认)
        var buf=Buffer.alloc(21);
        buf[0]=0x50;buf[1]=0x00;
        buf[2]=0x00;buf[3]=0xFF;buf[4]=0xFF;buf[5]=0x03;
        buf[6]=stationNo||0;buf[7]=0x0C;buf[8]=0x00;
        buf[9]=0x10;buf[10]=0x00;
        buf[11]=0x01;buf[12]=0x04;
        buf[13]=BIT_DEVICES[regType]?0x01:0x00;buf[14]=0x00;  // 0001=bit 0000=word
        buf[15]=startAddr&0xFF;buf[16]=(startAddr>>8)&0xFF;buf[17]=(startAddr>>16)&0xFF;
        buf[18]=deviceCode;
        buf[19]=wordCount&0xFF;buf[20]=(wordCount>>8)&0xFF;
        return buf;
    }

    function parseMCResponse(buf, startAddr, regType){
        if(!buf||buf.length<11)return null;
        var subheader=buf[0]===0xD0?0x50:(buf[0]===0xD4?0xD4:0);
        if(subheader===0)return null;
        var endCode=buf.readUInt16LE(9);
        if(endCode!==0)return null;
        var dataLen=buf.readUInt16LE(7)-2;
        var dataStart=(mcFrame==='4E'&&pp.serialNo!=null&&pp.serialNo!==0)?13:11;
        if(buf.length<dataStart+dataLen)return null;
        var result={};
        if(BIT_DEVICES[regType]){
            // 位元件: 0401 0001逐点读, 响应每字节一个位(0x00=OFF 0x01=ON)
            for(var i=0;i<dataLen;i++){
                result[regType+(startAddr+i)]=buf[dataStart+i]?1:0;
            }
        }else{
            // 字元件: 每个地址1个16位有符号整数
            for(var i=0;i<dataLen/2;i++){
                result[regType+(startAddr+i)]=buf.readInt16LE(dataStart+i*2);
            }
        }
        return result;
    }

    function processGroup(gi){
        if(gi>=regGroups.length){
            done({deviceId:dev.deviceId,deviceName:dev.deviceName,success:!hasFailed,data:allStdData,plcIp:dev.connection.ip,plcPort:dev.connection.port,error:hasFailed?firstError:null,driverType:'driver-mc-protocol'});
            return;
        }
        var grp=regGroups[gi];
        var addrs=grp.tags.map(function(t){return t.addr;});
        var startA=addrs[0];
        var wordCount=addrs[addrs.length-1]-startA+1;

        function attemptGroup(attempt){
            if(attempt>dev.maxRetries){
                hasFailed=true;
                if(!firstError)firstError='MC read failed for '+grp.regType+startA;
                processGroup(gi+1);
                return;
            }
            var client=new net.Socket();
            var buf=Buffer.alloc(0);
            var resolved=false;
            client.setTimeout(dev.timeout);

            client.connect(dev.connection.port, dev.connection.ip, function(){
                var frame=buildMCFrame(startA, wordCount, pp.stationNo||0, grp.regType, mcFrame);
                client.write(frame);
            });

            client.on('data', function(chunk){
                buf=Buffer.concat([buf, chunk]);
                var hdrLen=(mcFrame==='4E'&&pp.serialNo!=null&&pp.serialNo!==0)?13:11;
                if(!resolved&&buf.length>=hdrLen){
                    var dataLen=buf.readUInt16LE(7)-2;
                    if(buf.length>=hdrLen+dataLen){
                        resolved=true;
                        var raw=parseMCResponse(buf, startA, grp.regType);
                        if(raw){
                            grp.tags.forEach(function(t){
                                var key=grp.regType+t.addr;
                                var rv=raw[key];
                                var q=0;
                                if(rv===undefined||rv===null){q=2;}

                                allStdData[t.id]={rawValue:rv,quality:q,ts:new Date().toLocaleString('sv-SE').replace(' ','T')};
                            });
                            processGroup(gi+1);
                        }else{
                            client.destroy();setTimeout(function(){attemptGroup(attempt+1);},dev.retryInterval);
                        }
                    }
                }
            });

            client.on('timeout',function(){resolved=true;client.destroy();setTimeout(function(){attemptGroup(attempt+1);},dev.retryInterval);});
            client.on('error',function(e){if(resolved)return;resolved=true;try{client.destroy();}catch(e2){}setTimeout(function(){attemptGroup(attempt+1);},dev.retryInterval);});
            client.on('close',function(){if(!resolved){resolved=true;if(buf.length===0){hasFailed=true;if(!firstError)firstError='TCP closed (no data)';processGroup(gi+1);}else{client.destroy();setTimeout(function(){attemptGroup(attempt+1);},dev.retryInterval);}}});
        }
        attemptGroup(0);
    }

    processGroup(0);
}

