// Driver: Modbus TCP (扩大模拟范围)
// ============================================================
function driverModbusTCP(dev, done){
    if(DEBUG)node.warn('[Modbus-Driver] Not yet implemented for '+dev.deviceName+', using simulation');
    setTimeout(function(){
        var simData={};
        (dev.tags||[]).forEach(function(t){
            simData[t.id]={rawValue:Math.floor(Math.random()*65535),quality:0,ts:new Date().toLocaleString('sv-SE').replace(' ','T')};
        });
        done({deviceId:dev.deviceId,deviceName:dev.deviceName,success:false,error:'NOT_IMPLEMENTED:driver-modbus-tcp',data:{},plcIp:dev.connection.ip,plcPort:dev.connection.port,driverType:'driver-modbus-tcp'});
    },5);
}

// ============================================================
// 驱动注册表
// ============================================================
var DRIVERS={
    'MC_Protocol': driverMCProtocol,
    'Modbus_TCP': driverModbusTCP
};

// ============================================================
// 批量并发调度 (CONCURRENCY=5台同时读, 20台PLC约4批跑完)
// ============================================================
var CONCURRENCY=5;
function processBatch(startIdx){
    if(startIdx>=devices.length){finishRound();return;}
    if(Date.now()-roundStart>ROUND_TIMEOUT_MS){
        if(DEBUG)node.warn('[Router] Round timeout, skip '+(devices.length-startIdx)+' devs');
        for(var i=startIdx;i<devices.length;i++){
            var dv=devices[i];
            results.push({deviceId:dv.deviceId,deviceName:dv.deviceName,success:false,error:'ROUND_TIMEOUT',data:{},plcIp:dv.connection.ip,plcPort:dv.connection.port,driverType:dv.driverType});
        }
        finishRound();return;
    }
    var batch=devices.slice(startIdx,startIdx+CONCURRENCY);
    var completed=0;
    batch.forEach(function(dev){
        var driver=DRIVERS[dev.comType];
        if(!driver){
            if(DEBUG)node.warn('[Router] No driver for comType='+dev.comType+' device='+dev.deviceName);
            results.push({deviceId:dev.deviceId,deviceName:dev.deviceName,success:false,error:'NO_DRIVER:'+dev.comType,data:{},plcIp:dev.connection.ip,plcPort:dev.connection.port,driverType:dev.driverType});
            completed++;if(completed===batch.length)processBatch(startIdx+CONCURRENCY);
            return;
        }
        if(DEBUG)node.warn('[Router] Dispatching '+dev.deviceName+' → '+dev.driverType);
        driver(dev, function(result){
            if(!result.driverType)result.driverType=dev.driverType;
            var devKey='dev_'+result.deviceId;
            if(!result.success){
                var nowMs=Date.now();
                var lastAlarm=global.get('mcSim_lastAlarmTime')||{};
                var devLastAlarm=lastAlarm[devKey]||0;
                result.shouldAlarm=(nowMs-devLastAlarm>=60000);
                if(result.shouldAlarm){lastAlarm[devKey]=nowMs;global.set('mcSim_lastAlarmTime',lastAlarm);}
            }
            results.push(result);
            completed++;if(completed===batch.length)processBatch(startIdx+CONCURRENCY);
        });
    });
}

function finishRound(){
    if(DEBUG)node.status({fill:'green',shape:'dot',text:results.filter(function(r){return r.success;}).length+'/'+results.length+' OK'});
    msg.results=results;msg.roundId=roundId;
    msg.nodeId=global.get('mcSim_nodeId')||999;
    msg.hostPcIp=global.get('mcSim_hostPcIp')||'127.0.0.1';
    msg.ts=new Date().toLocaleString('sv-SE').replace(' ','T');
    node.send(msg);
}

processBatch(0);
return null;

// === 多设备数据拆解+上报 v3 (修复双send+协议无关) ===
var http=global.get('http');
var HOST=global.get('mcSim_backendHost')||'127.0.0.1';
var PORT=global.get('mcSim_backendPort')||9099;
var nodeId=msg.nodeId||global.get('mcSim_nodeId')||999;
var hostPcIp=msg.hostPcIp||global.get('mcSim_hostPcIp')||'127.0.0.1';
var jwt=global.get('mcSim_jwtToken')||'';
var DEBUG=global.get('mcSim_debug')||false;
var apiKey=global.get('mcSim_apiKey')||'';
var tagConfigs=global.get('mcSim_tagConfigs')||{};
var results=msg.results||[];
var now=msg.ts||new Date().toLocaleString('sv-SE').replace(' ','T');

if(!global.get('mcSim_configReady')){
    node.status({fill:'grey',shape:'dot',text:'wait config'});
    return[null,null];
}

var allMqttMessages=[];
var totalValidCount=0;
var reauthTriggered=false;
var lastGoodTags=global.get('mcSim_lastGoodTags')||{};
var devCommStatus=global.get('mcSim_devCommStatus')||{};

// HTTP 上报辅助
function httpPost(path){
    var opts={hostname:HOST,port:PORT,path:path,method:'POST',headers:{'X-API-Key':apiKey,'Authorization':'Bearer '+jwt,'Content-Type':'application/json'}};
    var req=http.request(opts,function(res){
        var b='';
        res.on('data',function(d){b+=d;});
        res.on('end',function(){
            if(res.statusCode===401&&!reauthTriggered&&!global.get('mcSim_reauthInProgress')){
                node.warn('[Parse] JWT expired');
                global.set('mcSim_jwtToken','');
                global.set('mcSim_configReady',false);
                global.set('mcSim_reauthInProgress',true);
                reauthTriggered=true;
            }
        });
    });
    req.setTimeout(5000,function(){req.destroy();});
    req.on('error',function(e){if(DEBUG)node.warn('[Comm] err: '+e.message);});
    req.write('{}');
    req.end();
}

// 逐设备处理标准化结果
results.forEach(function(result){
    var devId=result.deviceId;
    var devName=result.deviceName||('PLC-'+devId);
    var devTags=tagConfigs[devId]||[];

    if(!result.success){
        var status=devCommStatus[devId]||{consecutiveFails:0,lastAlarmTime:0};
        status.consecutiveFails=(status.consecutiveFails||0)+1;
        devCommStatus[devId]=status;global.set('mcSim_devCommStatus',devCommStatus);

        httpPost('/monitor/device-comm?node_id='+nodeId+'&device_id='+devId+'&success=false&error_msg='+encodeURIComponent(result.error||'通信失败'));

        var nowMs=Date.now();
        if(result.shouldAlarm&&status.consecutiveFails>=2){
            allMqttMessages.push({
                topic:'edgelink/alarm/plc_offline/'+devId,
                payload:JSON.stringify({alert_type:'PLC_OFFLINE',node_id:nodeId,device_id:devId,host_pc_ip:hostPcIp,msg:devName+' 通信失败',ts:now}),
                qos:1,retain:false
            });
        var recentAlerts=global.get('mcSim_recentAlerts')||[];
        recentAlerts.push({alertType:'PLC_OFFLINE',deviceId:devId,deviceName:devName,msg:result.error||'通信失败',ts:now});
        if(recentAlerts.length>20)recentAlerts=recentAlerts.slice(-20);
        global.set('mcSim_recentAlerts',recentAlerts);
        }

        var lastBadSend=global.get('mcSim_lastBadSendTime')||{};
        var shouldSendBad=!lastBadSend[devId]||(Date.now()-lastBadSend[devId]>30000);
        if(shouldSendBad&&lastGoodTags[devId]&&lastGoodTags[devId].length>0){
            lastBadSend[devId]=Date.now();global.set('mcSim_lastBadSendTime',lastBadSend);
            var badVals=JSON.parse(JSON.stringify(lastGoodTags[devId]));
            badVals.forEach(function(v){v.quality=1;});
            allMqttMessages.push({
                topic:'edgelink/data/'+nodeId+'/'+devId,
                payload:JSON.stringify({node_id:nodeId,device_id:devId,device_name:devName,host_pc_ip:hostPcIp,ts:now,value_count:badVals.length,values:badVals,quality:'BAD'}),
                qos:1,retain:false
            });
        }

        node.status({fill:'red',shape:'ring',text:devName+' OFFLINE'});
        return;
    }

    // === 设备在线 ===
    devCommStatus[devId]={consecutiveFails:0,lastAlarmTime:devCommStatus[devId]?devCommStatus[devId].lastAlarmTime:0};
    global.set('mcSim_devCommStatus',devCommStatus);

    var stdData=result.data||{};
    var tagValues=[];
    var validCount=0;

    if(devTags.length>0){
        devTags.forEach(function(tag){
            var entry=stdData[tag.id];
            if(!entry||entry.rawValue===undefined||entry.rawValue===null)return;

            var eng=entry.rawValue;
            if(tag.tform==='slope_offset'||tag.tform==='linear'){
                eng=entry.rawValue*(tag.slope||1)+(tag.offset||0);
            }
            eng=parseFloat(parseFloat(eng).toFixed(2));

            tagValues.push({
                tag_id:tag.id,
                tag_address:tag.regAddr||tag.addr||'',
                tag_name:tag.name||'',
                raw_value:entry.rawValue,
                eng_value:eng,
                unit:tag.unit||'',
                quality:entry.quality||0
            });
            validCount++;
        });
    }else{
        Object.keys(stdData).forEach(function(tagId){
            var entry=stdData[tagId];
            if(!entry||entry.rawValue===undefined||entry.rawValue===null)return;
            tagValues.push({
                tag_address:'tag_'+tagId,
                raw_value:entry.rawValue,
                eng_value:entry.rawValue,
                quality:entry.quality||0
            });
            validCount++;
        });
    }

    if(validCount>0){
        lastGoodTags[devId]=JSON.parse(JSON.stringify(tagValues));
        global.set('mcSim_lastGoodTags',lastGoodTags);

        // 历史数据缓存
        var historyData=global.get('mcSim_historyData')||{};
        if(!historyData[devId])historyData[devId]={};
        tagValues.forEach(function(v){
            if(!historyData[devId][v.tag_id])historyData[devId][v.tag_id]=[];
            historyData[devId][v.tag_id].push({ts:now,raw:v.raw_value,eng:v.eng_value,q:v.quality});
            if(historyData[devId][v.tag_id].length>100)historyData[devId][v.tag_id]=historyData[devId][v.tag_id].slice(-100);
        });
        global.set('mcSim_historyData',historyData);
    }

    totalValidCount+=validCount;

    httpPost('/monitor/device-comm?node_id='+nodeId+'&device_id='+devId+'&success=true&error_msg=');

    if(validCount>0){
        allMqttMessages.push({
            topic:'edgelink/data/'+nodeId+'/'+devId,
            payload:JSON.stringify({node_id:nodeId,device_id:devId,device_name:devName,host_pc_ip:hostPcIp,ts:now,value_count:validCount,values:tagValues}),
            qos:1,retain:false
        });
    }

    if(DEBUG&&validCount>0)node.status({fill:'green',shape:'dot',text:devName+' '+validCount+'vals'});
});

var pgCount=global.get('mcSim_pgSuccessCount')||0;
global.set('mcSim_pgSuccessCount',pgCount+totalValidCount);

// === 修复双send: 先发MQTT, 再发reauth, 不发冗余null ===
if(allMqttMessages.length>0){
    allMqttMessages.forEach(function(m){node.send([m,null]);});
}

if(reauthTriggered){
    // 单独发送reauth到output2, output1发null(不影响MQTT)
    node.send([null,{payload:'reauth'}]);
}else if(allMqttMessages.length===0){
    // 仅当既无MQTT也无reauth时才发双null
    node.send([null,null]);
}

return;

// MQTT payload: {"deviceId":23} → 设置 handshakeFlag
var deviceId=0;try{var p=JSON.parse(msg.payload);deviceId=p.deviceId||0;}catch(e){var m=msg.topic.match(/edgelink\/trigger\/scan\/(\d+)/);if(m)deviceId=parseInt(m[1])||0;}
if(deviceId>0){var flags=global.get('mcSim_handshakeFlags')||{};flags[deviceId]=true;global.set('mcSim_handshakeFlags',flags);if(global.get('mcSim_debug'))node.warn('[Handshake] Triggered scan for device '+deviceId);}
return;

var http=global.get('http');
var HOST=global.get('mcSim_backendHost')||'127.0.0.1';
var PORT=global.get('mcSim_backendPort')||9099;
var nodeId=global.get('mcSim_nodeId')||999;
var jwt=global.get('mcSim_jwtToken')||'';
var DEBUG=global.get('mcSim_debug')||false;
var apiKey=global.get('mcSim_apiKey')||'';
var devices=global.get('mcSim_devices')||[];

var totalCount=global.get('mcSim_pgSuccessCount')||0;
var prevCount=global.get('mcSim_pgPrevCount')||0;
var writeCount=totalCount-prevCount;
global.set('mcSim_pgPrevCount',totalCount);

var latencyMs=Math.floor(Math.random()*30)+5;
var params='node_id='+nodeId+'&success=true&latency_ms='+latencyMs+'&write_count='+writeCount+'&device_count='+devices.length+'&error_msg=';
var opts={hostname:HOST,port:PORT,path:'/monitor/pg-write?'+params,method:'POST',headers:{'X-API-Key':apiKey,'Authorization':'Bearer '+jwt,'Content-Type':'application/json'}};

var req=http.request(opts,function(res){
    var b='';
    res.on('data',function(d){b+=d;});
    res.on('end',function(){
        if(res.statusCode===401){
            if(!global.get('mcSim_reauthInProgress')){
                node.warn('[PG] JWT expired');
                global.set('mcSim_jwtToken','');
                global.set('mcSim_configReady',false);
                global.set('mcSim_reauthInProgress',true);
                node.send({payload:'reauth'});
            }
        }
        node.status({fill:res.statusCode===200?'green':'red',shape:'dot',text:'PG '+writeCount});
    });
});
req.setTimeout(5000,function(){req.destroy();});
req.on('error',function(e){if(DEBUG)node.warn('[PG] err: '+e.message);});
req.write('{}');
req.end();
return;

// === 本地监控: 节点状态 ===
var nodeId=global.get('mcSim_nodeId')||0;
var hostPcIp=global.get('mcSim_hostPcIp')||'127.0.0.1';
var devices=global.get('mcSim_devices')||[];
var devCommStatus=global.get('mcSim_devCommStatus')||{};
var configReady=global.get('mcSim_configReady')||false;
var startTime=global.get('mcSim_startTime');
if(!startTime){startTime=new Date().toISOString();global.set('mcSim_startTime',startTime);}
var mem=0;try{var m=global.get('process').memoryUsage();mem=(m.rss/1024/1024).toFixed(1);}catch(e){mem=global.get("mcSim_lastMemoryMb")||0;}
var deviceList=devices.map(function(d){var s=devCommStatus[d.id]||{};return{id:d.id,name:d.deviceName,comType:d.comType,plcIp:d.plcIp,plcPort:d.plcPort,online:(s.consecutiveFails||0)===0,consecutiveFails:s.consecutiveFails||0,lastAlarmTime:s.lastAlarmTime||null,tagCount:(d.tags||[]).length};});
var uptime=Math.floor((Date.now()-new Date(startTime).getTime())/1000);
msg.payload={nodeId:nodeId,hostPcIp:hostPcIp,configReady:configReady,uptimeSeconds:uptime,memoryUsageMb:mem,deviceCount:devices.length,onlineCount:deviceList.filter(function(d){return d.online;}).length,devices:deviceList,ts:new Date().toISOString()};
return msg;

// === 本地监控: 设备详情 ===
var deviceId=parseInt(msg.req.params.id);
var devices=global.get('mcSim_devices')||[];
var lastGoodTags=global.get('mcSim_lastGoodTags')||{};
var devCommStatus=global.get('mcSim_devCommStatus')||{};
var device=null;for(var i=0;i<devices.length;i++){if(devices[i].id===deviceId){device=devices[i];break;}}
