// 清除指定设备的告警抑制
var body={};try{body=JSON.parse(msg.payload);}catch(e){}
var deviceId=body.deviceId||parseInt(msg.req.query.deviceId)||0;
if(deviceId>0){var la=global.get('mcSim_lastAlarmTime')||{};delete la['dev_'+deviceId];global.set('mcSim_lastAlarmTime',la);}
